  function newRun(p,r){const id='wp-'+Date.now()+'-'+Math.random().toString(36).slice(2,9);return {schema:1,interactionVersion:4,contentRevision:p.contentRevision||0,runId:id,scratchId:id,problemId:p.id,routeId:r.id,sourceLocation:'',step:0,values:{},passed:{},attempts:{},firstPass:{},hints:{},seen:[],closure:[],conditionFound:[],conditionUsed:[],derivationSources:{},derived:{},verdict:'',reflection:'',customModel:'',discussion:'',assisted:false,example:false,finished:false,answersChecked:false,startedAt:new Date().toISOString()};}

