  function conditionContents(){const found=discoverConditions(),used=new Set(run.conditionUsed||[]),facts=problem.facts.filter(f=>found.includes(f.id)),done=facts.filter(f=>used.has(f.id)).length;return '<div class="wp-condition-heading"><h4>已找到的条件</h4><strong>'+done+' / '+facts.length+'</strong></div><p class="wp-condition-help">点击一条标记已用，再点可恢复；检验完成后统一标为已核对.</p>'+(facts.length?'<div class="wp-conditions-list">'+facts.map(f=>'<button type="button" class="wp-condition'+(used.has(f.id)?' is-used':'')+'" data-wp-condition="'+esc(f.id)+'" aria-pressed="'+used.has(f.id)+'"><span class="wp-condition-status">'+(used.has(f.id)?'✓':'○')+'</span><span><small>'+esc(sourceKinds[f.kind]||'题目条件')+'</small><span>'+esc(f.text)+'</span></span></button>').join('')+'</div>':'<p class="wp-condition-empty">在右侧填对并确认条件后，它会固定在这里.</p>')+(run.finished&&done===facts.length?'<p class="wp-condition-complete">✓ 全部条件已核对</p>':'');}
  function updateConditionPanel(){const box=host.querySelector('[data-wp-conditions]');if(!box||!run)return;const top=box.querySelector('.wp-conditions-list')?.scrollTop||0;box.innerHTML=conditionContents();const list=box.querySelector('.wp-conditions-list');if(list)list.scrollTop=top;for(const b of box.querySelectorAll('[data-wp-condition]'))b.onclick=()=>{if(!guard())return;const id=b.dataset.wpCondition,used=new Set(run.conditionUsed||[]);if(used.has(id))used.delete(id);else used.add(id);run.conditionUsed=[...used];updateConditionPanel();queueSave();};}
  function tableOptions(cell,ri,ci){const alternatives=[...(cell.alternatives||[]),...(T?.options(problem,route,ri,ci)||[])],ds=new Map((route.derivations||[]).map(d=>[d.id,d]));function requirements(ids){const refs=new Set();function visit(id){const d=ds.get(id);if(!d||refs.has(id))return;refs.add(id);for(const ref of d.sources||[])visit(ref);}for(const id of ids||[])visit(id);return [...refs].map(id=>({id,label:ds.get(id).label,completed:run.derived[id]===true}));}return {...cell,alternatives:alternatives.map(a=>({...a,requiredDerivations:requirements(a.sources)})),allowedNumbers:derivedNumbers(),sourceExpressions:(route.derivations||[]).filter(d=>run.derived[d.id]).flatMap(d=>[d.expr,d.result]),requiredDerivations:requirements(cell.sources)};}
