  function start(id,fresh=false,locationId=null){if(!guard())return;clearTimeout(searchTimer);save();problem=data.find(p=>p.id===id);if(!problem)return;const old=!fresh&&B.progress()?.drafts?.[id];route=problem.routes.find(r=>r.id===old?.routeId)||problem.routes[0];run=old?{...newRun(problem,route),...P.migrateDraft(old)}:newRun(problem,route);for(const [key,value]of Object.entries(run.values))if(key.startsWith('r:'))run.values[key]=R.normalizeToken(value);feedback='';feedbackKind='';if(old&&run.interactionVersion<2){const fresh=newRun(problem,route);run={...run,interactionVersion:4,runId:fresh.runId,scratchId:fresh.scratchId,step:0,seen:[],passed:{},firstPass:{},attempts:{},hints:{},finished:false,answersChecked:false};feedback='原分析记录已保留.这次从数值填空和关系拖拽重新核对.';feedbackKind='hint';}if(old&&(old.contentRevision||0)<(problem.contentRevision||0)){const sourceLocation=run.sourceLocation;run=newRun(problem,route);run.sourceLocation=problem.textbookSources.some(s=>s.id===sourceLocation)?sourceLocation:'';feedback='本题的表格或提问已更新，请从读题开始重新分析.以前已提交的记录完整保留.';feedbackKind='hint';}if(locationId!==null)run.sourceLocation=problem.textbookSources.find(s=>s.id===locationId)?.id||'';if(run.finished)run.step=6;observing=false;render();host.querySelector('h2')?.focus({preventScroll:true});}
