  function mergedSourcePanel(){const sources=(supplement.peopleEducation?.mergedSources||[]).filter(s=>s.problemIds.includes(problem.id));if(!sources.length)return '';return '<details class="wp-source-locations"><summary>合并题目与出处（'+sources.length+'组）</summary>'+sources.map(s=>'<p><b>'+esc(s.title)+'</b><br>'+esc(s.source)+'</p>'+(s.repeatSources||[]).map(v=>'<p>'+esc(v)+'</p>').join('')+'<p>'+esc(s.note)+'</p>').join('')+'</details>';}
  function originalPrompt(){return problem.originalStems?.[selectedSource()?.id]||problem.originalStem||problem.stem;}
  function originalFigure(){const f=problem.sourceFigure;if(!f)return '';const url=new URL('word-problems/'+f.file,scriptBase);url.searchParams.set('v',sourceVersion);return '<figure class="wp-original-figure" data-wp-source-figure><a href="'+esc(url.href)+'" target="_blank" rel="noopener" aria-label="查看配图大图：'+esc(f.alt)+'"><img src="'+esc(url.href)+'" alt="'+esc(f.alt)+'" decoding="async"></a><figcaption>按原书重绘 · 点击查看大图</figcaption></figure>';}
  function problemPanel(){const current=selectedSource(),otherSources=[...new Set([problem.source,...problem.textbookSources.map(s=>s.source)])].filter(s=>s!==(current?.source||problem.source));return '<aside class="wp-context" data-wp-current-problem="'+esc(problem.id)+'"><div class="wp-context-title"><span>'+esc(C.categoryFor(problem)?.label||problem.group)+' · '+esc(problem.kindLabel||kinds[problem.kind])+'</span><button type="button" class="wp-text-button" data-wp-catalog>题目目录</button></div><h3>'+esc(problem.title)+'</h3><details class="wp-original-problem" open><summary>原题与数据表</summary><p class="wp-stem">'+esc(originalPrompt())+'</p>'+originalFigure()+originalTable()+'</details>'+(problem.analysisNote?'<p class="wp-analysis-note"><b>本次分析说明：</b>'+esc(problem.analysisNote)+'</p>':'')+'<p class="wp-citation">'+esc(sourceCaption(current?.source||problem.source))+'</p>'+(otherSources.length?'<details class="wp-source-locations"><summary>其他出处与题目位置（'+otherSources.length+'处）</summary>'+otherSources.map(s=>'<p>'+esc(sourceCaption(s))+'</p>').join('')+'</details>':'')+mergedSourcePanel()+(problem.notices||[]).map(n=>'<p class="wp-notice">'+esc(n)+'</p>').join('')+(problem.diagram?'<details class="wp-observation"><summary>题目配图与数量关系</summary><div data-wp-observe></div></details>':'')+(run.step>0?'<div class="wp-current-variable"><span>当前设元</span><p>'+math(route.variable)+'：'+esc(route.meaning)+(route.unit?'（'+esc(route.unit)+'）':'')+'</p><small>'+esc(route.domain)+'</small></div>':'')+'<section class="wp-conditions" data-wp-conditions aria-label="已找到的条件">'+conditionContents()+'</section></aside>';}
  function answerPrefix(r,index){const a=r.answers?.[index];if(a&&Object.hasOwn(a,'variable'))return a.variable||'';const q=(r.equations||[]).find((q,qi)=>(q.answerIndex??qi)===index);if(q)return q.variable||r.variable;if(!(r.equations||[]).length&&(r.answers||[]).length===1)return r.variable;return '';}
  function input(key,label,options={}){const editor='<span class="wp-editor-host" data-wp-editor="'+esc(key)+'" data-wp-label="'+esc(label)+'"><input type="text" inputmode="url" autocorrect="off" autocapitalize="off" spellcheck="false" '+noCredential+' maxlength="350" aria-label="'+esc(label)+'" value="'+esc(run.values[key]||'')+'" data-wp-input="'+esc(key)+'" placeholder="'+esc(options.placeholder||'写出算式')+'"></span>';return '<label class="wp-answer-field"'+(options.hidden?' hidden':'')+'><span>'+esc(label)+'</span>'+(options.prefix?'<span class="wp-answer-input-line"><span class="wp-answer-prefix" aria-hidden="true">'+math(options.prefix)+' =</span>'+editor+'</span>':editor)+(options.unit?'<small>'+esc(options.unit)+'</small>':'')+'</label>';}
  function derivationCards(){return (route.derivations||[]).map((d,i)=>{const unlocked=(d.sources||[]).every(id=>!(route.derivations||[]).some(v=>v.id===id)||run.derived[id]);return '<article class="wp-derivation'+(!unlocked?' locked':'')+'" data-wp-derivation="'+esc(d.id)+'"><div class="wp-row-heading"><span class="wp-number">'+(i+1)+'</span><h4>'+esc(d.label)+'</h4>'+(run.derived[d.id]?'<span class="wp-success-tag">✓ 来源与计算正确</span>':'')+'</div><p>'+esc(d.explain)+'</p>'+(!unlocked?'<p>先完成前面的推导，才能使用它的结果.</p>':input('d:'+d.id,d.label+'的计算过程（写出来源算式即可，不必算出结果）',{placeholder:'写算式，也可写算式＝结果'})+'<fieldset class="wp-source-select"><legend>这一步用了哪些依据？</legend>'+[...problem.facts,...(route.derivations||[]).slice(0,i)].map(f=>'<label><input type="checkbox" data-wp-derived-source="'+esc(d.id)+'" value="'+esc(f.id)+'" '+((run.derivationSources[d.id]||[]).includes(f.id)?'checked':'')+'>'+esc(f.text||f.label)+'</label>').join('')+'</fieldset><button type="button" class="wp-secondary" data-wp-check-derived="'+esc(d.id)+'">核对这一步</button>')+(run.derived[d.id]?'<div class="wp-derived-chain">'+math(d.expr,true)+' = '+math(d.result)+'</div>':'')+'</article>';}).join('');}
  function cellExpression(cell){const derivation=(route.derivations||[]).find(d=>(cell.sources||[]).includes(d.id)&&E.normalize(cell.expr)===E.normalize(d.result));return derivation?'<span class="wp-cell-chain">'+math(derivation.expr,true)+' = '+math(derivation.result)+'</span>':math(cell.expr);}
  function displayCell(cell,ri,ci){if(!cell.given&&!cell.note&&run.passed[2]&&run.values['t:'+ri+':'+ci]){try{const result=checkCell(cell,ri,ci);if(result.ok)return {...cell,expr:result.expression||E.normalize(run.values['t:'+ri+':'+ci]).split('=').at(-1),sources:result.sources||cell.sources,sourceTrace:result.sourceTrace,sourceExpression:result.sourceExpression,explain:result.explain};}catch{}}return cell;}
  function cellSources(cell){
   const sources=(cell.sources||[]).map(source).filter(Boolean),derivations=sources.filter(f=>f.expr),types=[...new Set(sources.filter(f=>!f.expr).map(f=>sourceKinds[f.kind]||'题目条件'))];
   const tag=derivations.length?'已推导数据':cell.given?types.join(' · '):'由条件表示';
   return '<div class="wp-source-preview"><span>'+esc(tag)+'</span>'+derivations.filter(d=>E.normalize(cell.expr)!==E.normalize(d.result)).map(d=>'<div class="wp-source-chain"><small>'+esc(d.label)+'</small>'+math(d.expr,true)+' = '+math(d.result)+'</div>').join('')+(cell.explain?'<p>'+esc(cell.explain)+'</p>':'')+((cell.sourceTrace||[]).length>1?'<div class="wp-source-chain"><small>这两种写法表示同一个量</small>'+cell.sourceTrace.map(x=>math(x)).join(' = ')+'</div>':'')+'</div>'+sourceDetails(cell.sources||[]);
  }
  function table(showAll=false,canInsert=false){return '<div class="wp-table-scroll" tabindex="0" aria-label="数量表，可横向滚动"><table class="wp-quantity-table"><thead><tr>'+route.table.headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+route.table.rows.map((r,ri)=>'<tr><th scope="row">'+esc(r.label)+'</th>'+r.cells.map((original,ci)=>{const c=showAll||run.passed[2]?displayCell(original,ri,ci):original;return '<td>'+(c.note?'<span class="wp-cell-note">'+esc(c.note)+'</span>':showAll||c.given?'<div class="wp-cell-expression">'+cellExpression(c)+'</div>':input('t:'+ri+':'+ci,r.label+' · '+route.table.headers[ci+1]))+(!c.note&&c.sources?cellSources(c):'')+(canInsert&&c.expr?'<button type="button" class="wp-take-value" data-wp-take="'+ri+':'+ci+'" aria-label="把'+esc(r.label+' · '+route.table.headers[ci+1])+'放入当前方程">取用此量</button>':'')+'</td>';}).join('')+'</tr>').join('')+'</tbody></table></div>';}
  function bindTableValues(){host.querySelectorAll('[data-wp-take]').forEach(b=>{b.addEventListener('pointerdown',e=>e.preventDefault());b.onclick=()=>{
   if(!guard()||run.step!==3||manual())return;let field=activeField;
   if(!field?.isConnected||!field.closest('[data-wp-editor]')?.dataset.wpEditor.startsWith('e:'))field=host.querySelector('.wp-equation-entry math-field,.wp-equation-entry [data-wp-input]');
   if(!field)return;activeField=field;const [ri,ci]=b.dataset.wpTake.split(':').map(Number),cell=displayCell(route.table.rows[ri].cells[ci],ri,ci),value='('+cell.expr+')';
   if(field.tagName==='MATH-FIELD')field.insert(E.format(value),{focus:false,scrollIntoView:false});
   else{const start=field.selectionStart??field.value.length,end=field.selectionEnd??start;field.value=field.value.slice(0,start)+value+field.value.slice(end);field.focus({preventScroll:true});field.setSelectionRange(start+value.length,start+value.length);}
   field.dispatchEvent(new Event('input',{bubbles:true}));
  };});}
  function readingCards(){return '<div class="wp-read-facts">'+F.build(problem).facts.map((f,i)=>'<div class="wp-fact-line"><small class="wp-fact-kind">'+esc(sourceKinds[f.kind]||'题目条件')+'</small>'+(f.fields.length?'<div>'+f.parts.map(part=>{if(part.type==='text')return esc(part.text);const field=part.field;return '<input class="wp-fact-number" type="text" inputmode="'+(field.type==='fraction'?'text':'decimal')+'" '+noCredential+' maxlength="60" size="'+Math.max(3,Math.min(14,String(field.answer).length+1))+'" aria-label="'+esc((sourceKinds[f.kind]||'题目条件')+'第'+(i+1)+'条，第'+(field.index+1)+'个数')+'" value="'+esc(run.values[field.key]||'')+'" data-wp-fact="'+esc(field.key)+'" placeholder="填数">';}).join('')+'</div>':'<label><input type="checkbox" data-wp-seen="'+esc(f.id)+'" '+(run.seen.includes(f.id)?'checked':'')+'><span>'+esc(f.text)+'</span></label>')+'</div>').join('')+'</div>';}
  function relationSummary(){
   if(problem.id==='TB-R01'&&run.step===2)return '';
   const model=R.reference(problem,route);if(!model.count)return '';
   return '<details class="wp-relation-reference"><summary>查看列式依据</summary><div>'+[['sum','加和关系','＋'],['product','乘积关系','×']].filter(([kind])=>model[kind].length).map(([kind,name,operator])=>'<section><h4>'+name+'</h4>'+model[kind].map(row=>'<p>'+row.terms.map(esc).join(' '+operator+' ')+' ＝ '+esc(row.result)+'</p>').join('')+'</section>').join('')+'</div></details>';
  }
  function scratchEquations(){return '<div class="wp-scratch-equations"><h4>已列出的方程</h4>'+((route.equations||[]).length&&!manual()?route.equations.map((q,i)=>'<div data-wp-scratch-equation="'+i+'"><small>'+esc(q.label||'方程'+(i+1))+'</small><div class="wp-math-line">'+math(run.values['e:'+i]||'')+'</div></div>').join(''):manual()?'<p>'+esc(run.discussion||run.customModel||'结合题目条件，写下计算或分析过程.')+'</p>':'<p>按照数量表中的关系，写下计算过程.</p>')+'</div>';}
  function mountScratch(){const box=host.querySelector('[data-wp-scratch-mount]');if(!box)return;const pad=root.RatioWordProblemScratchpad;if(!pad){box.innerHTML='<p class="wp-notice">手写草稿暂未加载，可先在纸上演算，再核对答案.</p>';return;}scratchUI=pad.mount(box,{key:JSON.stringify([owner,run.scratchId||run.runId,problem.id,route.id]),headingHTML:scratchEquations()});}
  function checkLabel(){return run.step===5?((route.answers||[]).length?'核对答案':'确认分析结果'):run.step===6?'检验并保存':'确认本步';}
  function completion(){return run.finished?'<div class="wp-completion"><h4>本题分析已保存</h4><p>'+esc(manual()||run.customModel?'你的开放表达已保留，等待课堂讨论.':run.example?'本次记录为看过示范.':run.assisted?'本次记录为提示后完成.':'本次记录为独立完成.')+'</p><p data-wp-sync-status>本机已保存.</p><button type="button" class="wp-secondary" data-wp-restart aria-controls="wp-reset-confirm" aria-expanded="false">重置本题，重新分析</button></div>':'';}
  function verdictFields(){
   if((route.verdictCases||[]).length)return route.verdictCases.map((c,i)=>'<fieldset class="wp-verdict"><legend>'+esc(c.prompt||c.label)+'</legend>'+[['valid','符合本情形的要求'],['impossible','不符合本情形的要求']].map(([value,label])=>'<label><input type="radio" name="wp-case-'+i+'" data-wp-case="'+i+'" value="'+value+'" '+(run.values['v:'+i]===value?'checked':'')+'>'+esc(label)+'</label>').join('')+'</fieldset>').join('');
   return '<fieldset class="wp-verdict"><legend>'+esc(route.verdict?.prompt||'结合数量范围和题意，怎样判断？')+'</legend>'+Object.entries(verdicts).map(([v,l])=>'<label><input type="radio" name="wp-verdict" value="'+v+'" '+(run.verdict===v?'checked':'')+'>'+l+'</label>').join('')+'</fieldset>';
  }
  function stage(){
   if(run.step===0&&reverseModel())return '<h3>拆表：从给定方程找出数量</h3><p>把方程拆成两类对象各自的总价，再找出单价、数量和总价.笔记本是本次采用的一种示例.</p><div class="wp-math-line">'+math('3*x+2*(12-x)=32')+'</div><div class="wp-equation-parts"><p>'+math('3*x')+'：甲类单价 × 甲类数量</p><p>'+math('2*(12-x)')+'：乙类单价 × 乙类数量</p><p>'+math('32')+'：两类总价</p></div>'+readingCards();
   if(run.step===0)return '<h3>读题，把数量填完整</h3><p class="wp-reading-note">对照原题，把每个空格里的数补全；单位和百分号已经保留.没有数值的条件，请读懂后确认.性质和建模约定分别标明.</p>'+readingCards();
   if(run.step===1)return '<h3>选择未知量，推导需要的数据</h3><div class="wp-routes" role="group" aria-label="选择设元">'+problem.routes.map(r=>'<button type="button" data-wp-route="'+esc(r.id)+'" aria-pressed="'+(r.id===route.id)+'">'+esc(r.label)+'</button>').join('')+'</div><div class="wp-variable-definition">设 '+math(route.variable)+' 表示'+esc(route.meaning)+(route.unit?'，单位为'+esc(route.unit):'')+'.<p>'+esc(route.domain)+'</p>'+(route.additionalVariables||[]).map(v=>'<p>'+(v.known?'已知参数 ':'另设 ')+math(v.variable)+' 表示'+esc(v.meaning)+'（'+esc(v.unit)+'）；'+esc(v.domain)+'</p>').join('')+'</div>'+((route.derivations||[]).length?'<p>算式中保留题目原数或已完成的推导.也可以写成“算式＝结果”；只写化简后的数而没有来源，需要补写.</p>'+derivationCards():'<p class="wp-good-note">本题不需要预先计算新的数值.可引用已确认的题目条件、已学性质和建模约定，下一步用它们填写表达式.</p>')+'<details class="wp-own-model"><summary>我有其他设元方式</summary><p>写清未知数表示什么量、单位，以及你准备怎样列式.系统会保留给教师讨论.</p><textarea'+noCredential+' data-wp-custom maxlength="1600" aria-label="其他设元方式" placeholder="例如：设……为 y，单位是……">'+esc(run.customModel)+'</textarea></details>';
   if(run.step===2)return '<h3>把每个量放进数量表</h3><p>根据题目条件直接填写数量表.行写对象或阶段，列写具体数量；新数据先说明来源.</p>'+(manual()&&!reverseModel()?'<p class="wp-notice">本题还需要文字说明.先核对每个量的来源，再说明参数、整数条件或适用范围.</p>':'')+relationSummary()+table(manual()&&!reverseModel())+(route.tableNote?'<p class="wp-table-note">'+esc(route.tableNote)+'</p>':'')+(manual()&&!reverseModel()?'<label class="wp-writing">这张表表达了哪些关系？<textarea'+noCredential+' data-wp-discussion maxlength="2000" placeholder="说明一个表格中的表达式来自哪些条件.">'+esc(run.discussion)+'</textarea></label>':'');
   if(run.step===3)return '<h3>'+(reverseModel()?'根据数量表编写应用题':'找等量关系并列方程')+'</h3><p>'+(reverseModel()?'写清故事中的对象、单价、数量、总价及所求问题，使它对应给定方程.':'同一个量可以有不同的表示.根据表中数量必须满足的关系，列出能确定未知量的等式；恒等式不能代替求解方程.')+'</p>'+relationSummary(true)+(manual()?'<p class="wp-notice">'+esc(route.closure?.text||route.discussion||'说明所需的条件.')+'</p>':'')+(selectedAlternatives().length?'<p class="wp-good-note">'+esc(closureGuidance())+'</p>':'')+'<details class="wp-preview-table" open><summary>用数量表中的量列式</summary>'+table(true,!manual()&&(route.equations||[]).length>0)+'</details><section class="wp-equation-block"><h4>'+(manual()?esc(route.discussionTitle||'说明建模思路'):'根据上面的关系列方程')+'</h4>'+(!manual()&&(route.equations||[]).length?'<p class="wp-take-help">（可以点击表格中的“取用此量”）</p>':'')+'<p>'+esc(closureGuidance())+'</p>'+(manual()?'<label class="wp-writing">'+esc(route.discussion||'写出关系，并说明参数或适用范围.')+'<textarea'+noCredential+' data-wp-discussion maxlength="2000" placeholder="写出关系式，说明设元、已知参数、整数条件或适用范围.">'+esc(run.discussion)+'</textarea></label>':(route.equations||[]).length?route.equations.map((q,i)=>'<div class="wp-equation-entry">'+input('e:'+i,q.label||'根据关系列方程',{placeholder:'填写完整等式'})+'</div>').join(''):'<p class="wp-good-note">这是正向数量计算，按表中关系计算即可.</p>')+(!manual()&&(route.equations||[]).length?'<p class="wp-take-help">先选中方程输入框，再点击表格中的“取用此量”.运算符和等号由你补上.</p>':'')+'</section>';
   if(run.step===5)return '<h3>在草稿纸上解方程并确认答案</h3><p>'+(route.modelOnly?'原题要求列式，可在草稿上说明模型的含义，不必反推精确人数.':manual()?'在草稿上整理计算、整数筛选或判断理由，再确认所得结果.':'对照自己列出的方程演算，也可以在纸上完成.然后在本页填写答案并核对.')+'</p>'+(route.scratchPrompt?'<p class="wp-good-note" data-wp-scratch-prompt>'+esc(route.scratchPrompt)+'</p>':'')+'<div data-wp-scratch-mount></div><section class="wp-answer-confirm"><h4>确认解答</h4>'+((route.answers||[]).length?'<div class="wp-answer-grid">'+route.answers.map((a,i)=>input('a:'+i,a.label,{unit:a.unit,prefix:answerPrefix(route,i),placeholder:'填写演算得到的值'})).join('')+'</div>':'<p>本题在这里不要求填写数值答案，请确认上面的模型与论证，再进入原条件检验.</p>')+'</section>';
   if(run.step===6)return '<h3>用原条件检验</h3><p>解答已在上一页确认.本页只检查原条件、数量范围、单位和各个情形.</p>'+((route.answers||[]).length?'<details class="wp-confirmed-answers"><summary>回看已确认的解答</summary>'+route.answers.map((a,i)=>'<p>'+esc(a.label)+'：'+math(run.values['a:'+i]||a.expr)+' '+esc(a.unit||'')+'</p>').join('')+'</details>':'')+'<section class="wp-verification"><h4>代回题目检查</h4>'+(route.checks||[]).map((c,i)=>'<div class="wp-check-row"><div><p>'+esc(c.text)+'</p><div class="wp-math-line">'+math(c.expr,true)+' = </div></div>'+input('c:'+i,'检验'+(i+1)+'的计算结果',{placeholder:'计算结果'})+'</div>').join('')+verdictFields()+'</section>'+completion()+(run.passed[6]?solution():'');
   return "";
  }
  function solution(){return '<details class="wp-solution"'+(run.step===6?'':' open')+'><summary>完整推导与检验</summary>'+((route.derivations||[]).length?'<h4>数据怎样得到</h4>'+route.derivations.map(d=>'<p>'+esc(d.label)+'</p><div class="wp-math-line">'+math(d.expr,true)+' = '+math(d.result)+'</div>').join(''):'')+table(true)+'<h4>从关系到结果</h4>'+(route.steps||[]).map(s=>'<div class="wp-math-line">'+math(s)+'</div>').join('')+'<p>'+esc(route.conclusion)+'</p><p>'+esc(route.verdict?.explain)+'</p></details>';}
  function keyboard(){const vars=[...new Set([route.variable,...(route.additionalVariables||[]).map(v=>v.variable)])];return '<div class="wp-keypad"><div class="wp-keypad-heading"><span>公式键盘</span><button type="button" class="wp-text-button" data-wp-toggle-keypad aria-expanded="'+keypadOpen+'">'+(keypadOpen?'隐藏':'显示')+'</button></div><div class="wp-keypad-preview" data-wp-keypad-preview>先选择一个输入框，再写算式.</div><div class="wp-keys"'+(keypadOpen?'':' hidden')+'>'+['7','8','9','÷','(',')','4','5','6','×','分数','%','1','2','3','−','+','=','0','.',...vars,'⌫','清空'].map(k=>'<button type="button" data-wp-key="'+esc(k)+'" aria-label="'+esc(k==='分数'?'插入分数':k==='⌫'?'删除一个符号':k)+'">'+(k==='分数'?'<span class="wp-fraction-icon"><i>□</i><i>□</i></span>':esc(k))+'</button>').join('')+'</div></div>';}
  function resetConfirmation(){return '<div id="wp-reset-confirm" class="wp-reset-confirm" data-wp-reset-confirm hidden role="group" aria-label="确认重置本题"><strong>重置本题分析？</strong><p id="wp-reset-description">本次填写、勾选、步骤进度和草稿纸将重新开始，返回“读题找量”.已提交的历史记录会保留.</p><div><button type="button" class="wp-secondary" data-wp-cancel-reset>取消</button><button type="button" class="wp-primary" data-wp-confirm-reset aria-describedby="wp-reset-description">确认重置</button></div></div>';}
  function requestReset(button){if(!guard()||!run)return;const panel=host.querySelector('[data-wp-reset-confirm]');if(!panel)return;resetTrigger=button;panel.hidden=false;host.querySelectorAll('[data-wp-restart]').forEach(b=>b.setAttribute('aria-expanded','true'));panel.scrollIntoView({block:'nearest',behavior:'smooth'});panel.querySelector('[data-wp-cancel-reset]')?.focus({preventScroll:true});}
  function cancelReset(){if(!guard())return;const panel=host.querySelector('[data-wp-reset-confirm]');if(panel)panel.hidden=true;host.querySelectorAll('[data-wp-restart]').forEach(b=>b.setAttribute('aria-expanded','false'));if(resetTrigger?.isConnected)resetTrigger.focus({preventScroll:true});resetTrigger=null;}
