  function render(){if(!guard()||!run)return;clearInputBindings();resetTrigger=null;scratchUI?.destroy();scratchUI=null;renderToken++;activeField=null;mathFields=[];
   host.innerHTML=header()+'<nav class="wp-steps" aria-label="分析步骤">'+visibleFlow().map((step,i)=>'<button type="button" class="'+(run.passed[step]?'is-completed':'')+'" data-wp-step="'+step+'" '+(step>0&&!run.passed[step-1]?'disabled':'')+' aria-current="'+(run.step===step?'step':'false')+'"><span>'+(run.passed[step]?'✓':i+1)+'</span>'+stepLabel(step)+'</button>').join('')+'</nav><div class="wp-workspace">'+problemPanel()+'<section class="wp-stage" aria-label="'+stepLabel(run.step)+'"><div class="wp-stage-top"><small>步骤 '+(visibleFlow().indexOf(run.step)+1)+' / '+visibleFlow().length+'</small><div class="wp-stage-tools"><span data-wp-save-status>'+(B.isTeacher()?'教师演示':'过程自动保存在当前账号')+'</span><button type="button" class="wp-text-button wp-reset-button" data-wp-restart aria-controls="wp-reset-confirm" aria-expanded="false">↺ 重置本题</button></div></div>'+resetConfirmation()+stage()+'<div class="wp-feedback '+esc(feedbackKind)+'" role="status" aria-live="polite">'+feedbackHTML()+'</div><div class="wp-actions"><div>'+(run.step===5?'':'<button type="button" class="wp-text-button" data-wp-hint>给我一点提示</button><button type="button" class="wp-text-button" data-wp-example>查看本步示范</button>')+'</div><div>'+(run.step>0?'<button type="button" class="wp-secondary" data-wp-prev>上一步</button>':'')+(!run.finished||run.step===5?'<button type="button" class="wp-primary" data-wp-check>'+checkLabel()+'</button>':'')+(run.step<6?'<button type="button" class="wp-primary" data-wp-next '+(!run.passed[run.step]?'disabled':'')+'>'+(run.step===5?'进入检验 →':'下一步 →')+'</button>':'<button type="button" class="wp-primary" data-wp-catalog>返回题目目录</button>')+'</div></div><div data-wp-keyboard-slot></div></section></div>';
   bindHome();bind();bindTableValues();updateConditionPanel();mountScratch();if(host.querySelector('[data-wp-editor]')){host.querySelector('[data-wp-keyboard-slot]').innerHTML=keyboard();bindKeys();void installEditors(renderToken);}save();
  }
  function bind(){
   host.querySelectorAll('[data-wp-catalog]').forEach(b=>b.onclick=catalog);host.querySelectorAll('[data-wp-step]').forEach(b=>b.onclick=()=>{const next=Number(b.dataset.wpStep);if(next>0&&!run.passed[next-1])return;save();run.step=next;feedback='';render();});
   host.querySelector('[data-wp-prev]')?.addEventListener('click',()=>{save();run.step=visibleFlow()[Math.max(0,visibleFlow().indexOf(run.step)-1)];feedback='';render();});host.querySelector('[data-wp-next]')?.addEventListener('click',()=>{if(!run.passed[run.step])return;run.step=visibleFlow()[visibleFlow().indexOf(run.step)+1];feedback='';render();host.querySelector('.wp-stage h3')?.scrollIntoView({block:'start',behavior:'smooth'});});
   host.querySelector('[data-wp-check]')?.addEventListener('click',checkStage);host.querySelector('[data-wp-hint]')?.addEventListener('click',hint);host.querySelector('[data-wp-example]')?.addEventListener('click',example);
   host.querySelectorAll('[data-wp-fact]').forEach(input=>{bindMathInput(input,{numberOnly:true,inputMode:input.getAttribute('inputmode')==='text'?'url':'decimal',onChange:value=>{if(!guard())return;run.values[input.dataset.wpFact]=value;input.removeAttribute('aria-invalid');invalidate(0);updateConditionPanel();queueSave();}});input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();checkStage();}};});
   host.querySelectorAll('[data-wp-seen]').forEach(c=>c.onchange=()=>{run.seen=Array.from(host.querySelectorAll('[data-wp-seen]:checked')).map(x=>x.dataset.wpSeen);invalidate(0);updateConditionPanel();queueSave();});
   host.querySelectorAll('[data-wp-route]').forEach(b=>b.onclick=()=>{if(b.dataset.wpRoute===route.id)return;const seen=run.seen,found=run.conditionFound,sourceLocation=run.sourceLocation,facts=Object.fromEntries(Object.entries(run.values).filter(([key])=>key.startsWith('f:')));route=problem.routes.find(r=>r.id===b.dataset.wpRoute);run=newRun(problem,route);run.seen=seen;run.conditionFound=found;run.values=facts;run.sourceLocation=sourceLocation;run.passed[0]=true;run.step=1;render();});
   host.querySelectorAll('[data-wp-input]').forEach(i=>{bindMathInput(i,{variables,onChange:value=>changed(i.dataset.wpInput,value),onFocus:()=>{activeField=i;updateKeyboardPreview();}});});
   host.querySelectorAll('[data-wp-derived-source]').forEach(c=>c.onchange=()=>{const id=c.dataset.wpDerivedSource;run.derivationSources[id]=Array.from(host.querySelectorAll('[data-wp-derived-source]')).filter(x=>x.dataset.wpDerivedSource===id&&x.checked).map(x=>x.value);invalidateDerived(id);invalidate(1);queueSave();});
   host.querySelectorAll('[data-wp-check-derived]').forEach(b=>b.onclick=()=>checkDerived(b.dataset.wpCheckDerived));
   host.querySelectorAll('[data-wp-case]').forEach(c=>c.onchange=()=>{run.values['v:'+c.dataset.wpCase]=c.value;invalidate(6,false);queueSave();});
   host.querySelectorAll('[name="wp-verdict"]').forEach(c=>c.onchange=()=>{if(!guard())return;run.verdict=c.value;invalidate(6,false);queueSave();});
   for(const [selector,key]of [['[data-wp-custom]','customModel'],['[data-wp-discussion]','discussion']]){const el=host.querySelector(selector);if(el)el.oninput=()=>{if(!guard())return;run[key]=el.value;invalidate(run.step);queueSave();};}
   host.querySelectorAll('[data-wp-restart]').forEach(b=>b.addEventListener('click',()=>requestReset(b)));
   host.querySelector('[data-wp-cancel-reset]')?.addEventListener('click',cancelReset);
   host.querySelector('[data-wp-confirm-reset]')?.addEventListener('click',resetAnalysis);
   host.querySelector('[data-wp-reset-confirm]')?.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();cancelReset();}});
   const observe=host.querySelector('.wp-observation');if(observe){observe.open=observing;observe.addEventListener('toggle',()=>{observing=observe.open;if(observing){const box=observe.querySelector('[data-wp-observe]');if(!box.dataset.mounted){root.RatioWordProblemDiagrams?.mount(box,problem,route);box.dataset.mounted='1';}}});if(observing){root.RatioWordProblemDiagrams?.mount(observe.querySelector('[data-wp-observe]'),problem,route);observe.querySelector('[data-wp-observe]').dataset.mounted='1';}}
  }
  async function installEditors(token){try{await loadEditor();}catch{if(token===renderToken){const status=host.querySelector('[data-wp-save-status]');if(status)status.textContent='可直接输入算式；公式键盘稍后重试.';}return;}if(token!==renderToken||!ready())return;for(const container of host.querySelectorAll('[data-wp-editor]')){const old=container.querySelector('input');if(!old)continue;const key=container.dataset.wpEditor,mf=document.createElement('math-field');mf.mathVirtualKeyboardPolicy='manual';mf.smartFence=true;mf.defaultMode='math';mf.setAttribute('inputmode','url');mf.setAttribute('aria-label',container.dataset.wpLabel);mf.setAttribute('autocomplete','off');mf.setAttribute('data-lpignore','true');mf.setAttribute('data-1p-ignore','');mf.setAttribute('data-form-type','other');mf.value=run.values[key]||'';const wasActive=activeField===old;old.replaceWith(mf);bindMathInput(mf,{variables,onFocus:()=>{activeField=mf;updateKeyboardPreview();},onChange:value=>changed(key,value)});mf.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();checkStage();}});mathFields.push(mf);if(wasActive||!activeField)activeField=mf;}updateKeyboardPreview();}
  function updateKeyboardPreview(){const box=host.querySelector('[data-wp-keypad-preview]'),f=activeField;if(!box||!f)return;const value=f.value||'';let rendered='<span>等待输入</span>';if(value){try{rendered=root.katex.renderToString(M.preview(value),{throwOnError:true,output:'htmlAndMathml',strict:'ignore'});}catch{rendered='<span>请继续填写算式</span>';}}box.innerHTML='<small>'+esc(f.getAttribute('aria-label')||'当前算式')+'</small><div>'+rendered+'</div>'; }
  function bindKeys(){host.querySelector('[data-wp-toggle-keypad]').onclick=()=>{keypadOpen=!keypadOpen;const area=host.querySelector('.wp-keys'),b=host.querySelector('[data-wp-toggle-keypad]');area.hidden=!keypadOpen;b.textContent=keypadOpen?'隐藏':'显示';b.setAttribute('aria-expanded',String(keypadOpen));};host.querySelectorAll('[data-wp-key]').forEach(b=>{b.addEventListener('pointerdown',e=>e.preventDefault());b.onclick=()=>{let f=activeField;if(!f||!f.isConnected)f=host.querySelector('math-field,[data-wp-input]');if(!f)return;activeField=f;const k=b.dataset.wpKey;if(f.tagName==='MATH-FIELD'){if(k==='⌫')f.executeCommand('deleteBackward');else if(k==='清空'){f.executeCommand('selectAll');f.executeCommand('deleteBackward');}else f.insert(k==='分数'?'\\frac{#0}{#?}':({'×':'\\times','÷':'\\div','−':'-','%':'\\%'}[k]||k),{focus:false,scrollIntoView:false});f.dispatchEvent(new Event('input',{bubbles:true}));}else{f.focus({preventScroll:true});const start=f.selectionStart??f.value.length,end=f.selectionEnd??start;f.value=k==='清空'?'':k==='⌫'?f.value.slice(0,Math.max(0,start-1))+f.value.slice(end):f.value.slice(0,start)+(k==='分数'?'/':k)+f.value.slice(end);f.dispatchEvent(new Event('input',{bubbles:true}));}};});}
  function sameIds(a,b){return a.length===b.length&&a.every(x=>b.includes(x));}
  function feedbackHTML(){if(!feedback)return '';const kind=feedbackKind||'hint',heads={success:'检查正确',error:'还不正确',source:'还需补全依据',hint:'提示',recorded:'已记录，待讨论'},icons={success:'✓',error:'✕',source:'!',hint:'i',recorded:'✓'};return '<span class="wp-feedback-icon" aria-hidden="true">'+esc(icons[kind]||'i')+'</span><div><strong class="wp-feedback-title">'+esc(heads[kind]||'提示')+'</strong><p>'+esc(feedback)+'</p></div>';}
  function showFeedback(){const f=host.querySelector('.wp-feedback');if(!f)return;const urgent=feedbackKind==='error'||feedbackKind==='source';f.className='wp-feedback '+feedbackKind;f.setAttribute('role',urgent?'alert':'status');f.setAttribute('aria-live',urgent?'assertive':'polite');f.innerHTML=feedbackHTML();if(feedback)f.scrollIntoView?.({block:'nearest',behavior:'smooth'});}
  function fail(message,kind='error',step=run.step){run.attempts[step]=(Number(run.attempts[step])||0)+1;feedback=message;feedbackKind=kind;save();showFeedback();return false;}
  function pass(message='这一步的数量关系正确.'){run.passed[run.step]=true;if(reverseModel()&&run.step===0)run.passed[1]=true;if(run.step===3)run.passed[4]=true;if(!Object.hasOwn(run.firstPass,run.step))run.firstPass[run.step]=!(run.attempts[run.step]||run.hints[run.step]||run.example);feedback=message;feedbackKind=manual()&&((run.step===2&&!reverseModel())||run.step===3||(run.step===5&&!(route.answers||[]).length))?'recorded':'success';render();showFeedback();}
  function derivationContext(d){const parents=new Map();function visit(item){for(const id of item.sources||[]){const parent=(route.derivations||[]).find(x=>x.id===id);if(parent&&run.derived[id]&&!parents.has(id)){parents.set(id,parent);visit(parent);}}}visit(d);return {requireCalculation:true,allowedNumbers:[...parents.values()].map(p=>E.numeric(p.result)).filter(n=>n!==null),sourceExpressions:[...parents.values()].map(p=>p.expr)};}
  function checkDerived(id){if(!guard())return;const d=(route.derivations||[]).find(x=>x.id===id);if(!d)return;const result=E.checkDerivation(run.values['d:'+id]||'',{...d,...derivationContext(d)},route.variable);if(!result.ok)return fail(result.message,result.kind==='source'?'source':'error');if(!sameIds(run.derivationSources[id]||[],d.sources||[]))return fail('计算过程正确.再核对这一步实际用到的条件或约定.','source');run.derived[id]=true;markConditions(d.sources);feedback='来源和计算过程都正确.现在可以使用这个结果.';feedbackKind='success';render();}
  function checkStage(){if(!guard()||!run)return;const s=run.step;
   if(s===0){const reading=F.check(problem,run.values);if(!reading.ok){fail(reading.message,'source');const input=Array.from(host.querySelectorAll('[data-wp-fact]')).find(x=>x.dataset.wpFact===reading.key);input?.setAttribute('aria-invalid','true');input?.focus({preventScroll:true});return;}if(F.build(problem).facts.some(f=>!f.fields.length&&!run.seen.includes(f.id)))return fail('还有不含数值的条件没有确认，请读懂后勾选.','source');run.seen=problem.facts.map(f=>f.id);discoverConditions();return pass('题目中的数量已填写正确，条件已固定在左侧.');}
   if(s===1){if((route.derivations||[]).some(d=>!run.derived[d.id]))return fail('先逐项完成数据推导，并选择使用的依据.','source');for(const d of route.derivations||[])markConditions(d.sources);return pass('未知量和需要的数据已准备好.');}
   if(s===2){if(manual()&&!reverseModel()){if(run.discussion.trim().length<6)return fail('请用一句完整的话说明表中至少一个表达式的来源.');for(const row of route.table.rows)for(const c of row.cells)markConditions(c.sources);return pass('数量关系与说明已保留，下一页把关系连成等式.');}const used=[];for(let ri=0;ri<route.table.rows.length;ri++)for(let ci=0;ci<route.table.rows[ri].cells.length;ci++){const c=route.table.rows[ri].cells[ci];if(c.note)continue;if(c.given){used.push(...c.sources||[]);continue;}const result=checkCell(c,ri,ci);if(!result.ok)return fail(route.table.rows[ri].label+' · '+route.table.headers[ci+1]+'：'+result.message,result.kind==='source'?'source':'error');used.push(...result.sources||c.sources||[]);}markConditions(used);return pass('数量表已核对.等价写法及其来源会保留在表格中.');}
   if(s===3){if(manual()){if(run.discussion.trim().length<8)return fail('请写出数量关系，并说明设元、已知参数或适用条件.');markConditions(route.closure?.sources);return pass('模型说明已保留，继续演算与确认结果.');}for(let i=0;i<(route.equations||[]).length;i++){const q=route.equations[i],result=E.checkEquation(run.values['e:'+i]||'',q,q.variable||route.variable);if(!result.ok)return fail((q.label||'所列等式')+'：'+result.message,result.kind==='source'?'source':'error');if(!equationHasSources(run.values['e:'+i]||'',q))return fail('等式关系正确，但出现了尚未说明来源的新数.请使用表中已确认的量列式.','source');}markConditions([...(route.closure?.sources||[]),...selectedAlternatives().flatMap(a=>a.closureSources||[])]);return pass((route.equations||[]).length?'等量关系和方程已一起核对，可以开始演算.':'已明确计算关系，可以开始演算.');}
   if(s===5){if([0,1,2,3,4].some(i=>run.passed[i]!==true))return fail('请先完成前面的分析步骤.');scratchUI?.flush();for(let i=0;i<(route.answers||[]).length;i++){const a=route.answers[i];try{if(!E.equivalent(run.values['a:'+i]||'',a.expr,route.variable))return fail(a.label+'还不正确，请根据方程重新计算.');}catch(e){return fail(e.message);}}run.answersChecked=true;return pass('解答已确认.下一页只做原条件与实际意义的检验.');}
   if(s===6){if([0,1,2,3,4,5].some(i=>run.passed[i]!==true)||!run.answersChecked)return fail('请先在上一页确认解答.');for(let i=0;i<(route.checks||[]).length;i++){const c=route.checks[i];try{if(!E.equivalent(run.values['c:'+i]||'',c.result,route.variable))return fail('检验'+(i+1)+'的计算还不正确，请把结果代回原条件.');}catch(e){return fail(e.message);}}for(const [i,c] of (route.verdictCases||[]).entries()){if(run.values['v:'+i]!==c.correct)return fail(c.label+'：请分别核对这个情形的允许范围.');}if((route.verdictCases||[]).length)run.verdict=route.verdict?.correct||'multiple';if(run.verdict!==(route.verdict?.correct||'valid'))return fail('再检查整数、单位、取值范围、全部情形及条件是否充分.');return finishAnalysis();}
  }
  function finishAnalysis(){run.passed[6]=true;if(!Object.hasOwn(run.firstPass,6))run.firstPass[6]=!(run.attempts[6]||run.hints[6]||run.example);run.finished=true;markConditions(problem.facts.map(f=>f.id));save();try{B.complete(stateData(),problem,route);feedback=manual()?'分析过程已保存，模型与论证留待课堂讨论.':'原条件与实际意义检验正确，分析过程已保存.';feedbackKind=manual()?'recorded':'success';render();showFeedback();const current=run.runId;Promise.resolve(B.sync()).then(ok=>{if(!ready()||run?.runId!==current)return;const box=host.querySelector('[data-wp-sync-status]');if(box)box.textContent=B.isTeacher()?'教师演示不写入学生记录.':ok?'已同步到当前学生账号.':'本机已保存，暂未同步；联网后会继续尝试.';});}catch(e){run.finished=false;fail('保存未完成：'+e.message);}}
  function hint(){if(!guard())return;const n=(run.hints[run.step]||0)+1;run.hints[run.step]=n;run.assisted=true;const help=[['找到题中的对象、总量、变化和比较词.','“多几”与“共几”不同；百分数还需要确认基准量.'],['先写清未知数表示什么，再看哪些数据需要计算.','整体看作1是建模约定；增加25%时，原量的一份也要保留.'],['先确认每列是什么量、什么单位.','把题目给出的原数写进算式；每个量可点击“查看来源”.'],['找出当前表中数量还必须满足的独立条件.',closureGuidance()],['用表格中的量写完整等式，先不直接写解.',route.closure?.text||'说明方程与条件的关系.'],['对照已列出的方程，逐行写下等式变形.','等式两边进行同一种运算，再求出未知数.'],['把上一页已确认的解代回原题，逐条检查条件是否成立.','检查整数、单位、区间和不同情形.']];feedback=help[run.step][Math.min(n-1,1)];feedbackKind='hint';render();}
  function example(){if(!guard()||run.step===5)return;run.example=true;run.assisted=true;run.hints[run.step]=3;
   if(run.step===0){Object.assign(run.values,F.canonical(problem));run.seen=problem.facts.map(f=>f.id);}
   if(run.step===1){for(const d of route.derivations||[]){run.values['d:'+d.id]=E.format(d.expr);run.derivationSources[d.id]=d.sources||[];run.derived[d.id]=true;}}
   if(run.step===2){route.table.rows.forEach((r,ri)=>r.cells.forEach((c,ci)=>{if(c.expr&&!c.given)run.values['t:'+ri+':'+ci]=E.format(c.expr);}));if(manual())run.discussion=route.discussion||'请说明各数量的关系，并检查条件是否充分.';}
   if(run.step===3){(route.equations||[]).forEach((q,i)=>run.values['e:'+i]=E.format(q.left)+'='+E.format(q.right));if(manual())run.discussion=route.conclusion||route.discussion||'';}
   if(run.step===6){(route.checks||[]).forEach((c,i)=>run.values['c:'+i]=E.format(c.result));run.verdict=route.verdict?.correct||'valid';(route.verdictCases||[]).forEach((c,i)=>{run.values['v:'+i]=c.correct;});}
   feedback='本步已显示示范.本次会记录为看过示范，你仍可回到目录重新独立分析.';feedbackKind='hint';render();
  }
  function destroy(){save();clearInputBindings();scratchUI?.destroy();scratchUI=null;alive=false;renderToken++;clearTimeout(saveTimer);clearTimeout(searchTimer);mathFields=[];activeField=null;}
  return {open:catalog,start,destroy};
